"""Reader/file contracts; generated bytes follow the two clients' mfu_dump_t."""
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import Mock

import pytest
import hfmfuread
import read

UID = '04112233445566'


def dump(pages, version=0):
    header = bytearray(56)
    header[6], header[11] = version, pages - 1
    data = bytearray((n % 256 for n in range(pages * 4)))
    if pages >= 2:
        uid = bytes.fromhex(UID)
        data[:3], data[4:8] = uid[:3], uid[3:]
    return bytes(header + data)


@pytest.fixture
def device(monkeypatch, tmp_path):
    state = SimpleNamespace(data=dump(16), output='', result=1, commands=[])

    def task(command, timeout):
        state.commands.append((command, timeout))
        assert command.startswith('hf mfu dump -f ')
        state.path = Path(command.split(' -f ', 1)[1] + '.bin')
        if state.data is not None:
            state.path.write_bytes(state.data)
        return state.result

    monkeypatch.setattr(hfmfuread, 'appfiles', SimpleNamespace(PATH_DUMP_MFU=str(tmp_path)))
    monkeypatch.setattr(hfmfuread, 'executor', SimpleNamespace(
        startPM3Task=task, hasKeyword=lambda word: word in state.output))
    monkeypatch.setattr(hfmfuread, 'FILE_MFU_READ', 'previous-card.bin')
    return state


@pytest.mark.parametrize('typ,pages,version', [(2,16,0), (3,48,0), (4,20,0x0b),
    (4,41,0x0e), (4,20,0), (4,41,0), (5,45,0x0f), (6,135,0x11), (7,231,0x13)])
def test_complete_dump_retains_exact_bytes_and_path(device, typ, pages, version):
    device.data = dump(pages, version)
    result = hfmfuread.read({'type': typ, 'uid': UID})
    assert result == {'return': 0, 'file': str(device.path), 'partial': False, 'pages': pages}
    assert Path(result['file']).read_bytes() == device.data
    assert hfmfuread.FILE_MFU_READ == result['file']
    assert len(device.commands) == 1


@pytest.mark.parametrize('typ,pages,version,output', [
    (2,8,0,''), (3,44,0,'Partial dump created. (44 of 48 blocks)'),
    (4,20,0x0e,''), (4,20,0,'Partial dump created. (20 of 41 blocks)'),
    (5,16,0,''), (6,32,0,''), (7,32,0,'')])
def test_partial_data_is_preserved_and_explicit(device, typ, pages, version, output):
    device.data, device.output = dump(pages, version), output
    result = hfmfuread.read({'type': typ, 'uid': UID})
    assert result['return'] == 0 and result['partial'] is True
    assert result['pages'] == pages and Path(result['file']).read_bytes() == device.data


@pytest.mark.parametrize('data,output,result', [
    (None,'',1), (None,'Partial dump created',1), (b'','',1), (b'x'*55,'',1),
    (dump(16)[:-4],'',1), (dump(16)+b'xxxx','',1), (dump(16)[56:],'',1),
    (dump(256)+b'x','',1), (dump(17),'',1), (dump(1),'',1),
    (dump(16),'',-1), (dump(16),"Can't select card",1),
])
def test_invalid_or_unsuccessful_output_cannot_reuse_old_success(device, data, output, result):
    device.data, device.output, device.result = data, output, result
    assert hfmfuread.read({'type': 2, 'uid': UID}) == {'return': -1, 'file': ''}
    assert hfmfuread.FILE_MFU_READ is None


def test_wrong_card_dump_fails(device):
    assert hfmfuread.read({'type': 2, 'uid': '04776655443322'})['return'] == -1
    assert hfmfuread.FILE_MFU_READ is None


@pytest.mark.parametrize('infos', [{}, {'type': 2, 'uid': '../not-a-card'},
                                  {'type': 2, 'uid': None}, {'type': 99, 'uid': UID}])
def test_unknown_identity_does_not_start_command(device, infos):
    assert hfmfuread.read(infos)['return'] == -1
    assert not device.commands and hfmfuread.FILE_MFU_READ is None


def test_orphaned_json_is_not_overwritten_and_previous_dump_is_not_reused(device, tmp_path):
    old = tmp_path/('M0-UL_'+UID+'_1.bin')
    old.write_bytes(dump(16))
    orphan = tmp_path/('M0-UL_'+UID+'_2.json')
    orphan.write_text('previous evidence')
    result = hfmfuread.read({'type': 2, 'uid': UID})
    assert result['file'].endswith('_3.bin')
    assert old.read_bytes() == dump(16) and orphan.read_text() == 'previous evidence'


def test_exhausted_names_fail_before_command(device, monkeypatch):
    monkeypatch.setattr(hfmfuread.os.path, 'lexists', lambda path: True)
    assert hfmfuread.read({'type': 2, 'uid': UID})['return'] == -1
    assert not device.commands


def test_unreadable_file_fails(device, monkeypatch):
    def denied(*args, **kwargs):
        raise PermissionError('unreadable dump')
    monkeypatch.setattr(hfmfuread, 'open', denied, raising=False)
    assert hfmfuread.read({'type': 2, 'uid': UID})['return'] == -1


def test_real_reader_propagates_partial_without_changing_write_bundle(device):
    device.data = dump(8)
    reader = read.Reader()
    reader.call_reading, reader.call_exception = Mock(), Mock()
    reader.start(2, {'infos': {'type': 2, 'uid': UID}})
    reader._thread.join(2)
    assert not reader.is_reading()
    reader.call_exception.assert_not_called()
    reader.call_reading.assert_called_once_with({
        'success': True, 'tag_info': {'type': 2, 'uid': UID},
        'force': False, 'partial': True, 'bundle': str(device.path)})
